{
  "criteria": [
    {
      "kind": "exclusion",
      "text": "Ongoing or recent (within 5 years) evidence of significant autoimmune disease that required treatment with systemic immunosuppressive treatments, which may suggest higher risk for severe irAEs. The following are not exclusionary: vitiligo, childhood asthma that has resolved, type 1 diabetes, residual hypothyroidism that required only hormone replacement, or psoriasis that does not require systemic treatment.",
      "quote": "Ongoing or recent (within 5 years) evidence of significant autoimmune disease that required treatment with systemic immunosuppressive treatments",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Lesion size (ct/mri/caliper) at or above 8 mm.",
      "quote": "Lesion size (ct/mri/caliper) at or above 8 mm.",
      "thresholds": [
        {
          "test": "Lesion size",
          "op": ">=",
          "value": 8,
          "unit": "mm"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with other systemic immune-modulating agents that was (a) within fewer than 4 weeks (28 days) of the enrollment date, or (b) associated with irAEs of any grade within 90 days prior to enrollment, or (c) associated with toxicity that resulted in discontinuation of the immune-modulating agent. Examples include therapeutic vaccines, cytokine treatments (other than G-CSF or erythropoietin), or agents targeting CTLA-4, 4-1BB, PI3K-delta, LAG3, or OX-40.",
      "quote": "Prior treatment with other systemic immune-modulating agents that was (a) within fewer than 4 weeks (28 days) of the enrollment date, or (b) associated with irAEs of any grade within 90 days prior to enrollment, or (c) associated with toxicity that resulted in discontinuation of the immune-modulating agent.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Known history of brain metastasis(es) that may be considered active. Patients with previously treated brain metastases may participate if lesions are stable (no progression for at least 6 weeks on imaging), no new or enlarging brain metastases, and no immunosuppressive doses of systemic corticosteroids for brain metastases within 4 weeks of first dose.",
      "quote": "Known history of brain metastasis(es) that may be considered active",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Immunosuppressive corticosteroid doses (>10 mg prednisone daily or equivalent) within 4 weeks prior to the first dose of study drug. Patients requiring brief courses of steroids (e.g., for imaging prophylaxis) are not excluded.",
      "quote": "Immunosuppressive corticosteroid doses (>10 mg prednisone daily or equivalent) within 4 weeks prior to the first dose of study drug",
      "thresholds": [
        {
          "test": "prednisone dose",
          "op": ">",
          "value": 10,
          "unit": "mg/day"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Active bacterial, viral, fungal or mycobacterial infection requiring therapy, including known HIV, or active HBV or HCV. Active HBV is defined as positive surface antigen.",
      "quote": "Active bacterial, viral, fungal or mycobacterial infection requiring therapy, including known infection with human immunodeficiency virus (HIV), or active infection with hepatitis B virus (HBV) or hepatitis C virus (HCV).",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of pneumonitis within the last 5 years. Pneumonitis includes interstitial pneumonitis and active, non-infectious pneumonia, including interstitial lung disease.",
      "quote": "History of pneumonitis within the last 5 years.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any anticancer treatment (chemotherapy, targeted systemic therapy, photodynamic therapy), investigational, or standard of care, within 30 days of initial study drug administration or planned during study. Patients on bisphosphonates or denosumab are not excluded. Radiation therapy must be discontinued at least 14 days prior.",
      "quote": "Any anticancer treatment (chemotherapy, targeted systemic therapy, photodynamic therapy), investigational, or standard of care, within 30 days of the initial administration of study drug",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of documented allergic reactions or acute hypersensitivity reaction attributed to antibody treatments.",
      "quote": "History of documented allergic reactions or acute hypersensitivity reaction attributed to antibody treatments.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Concurrent malignancy other than cervical cancer and/or history of malignancy other than cervical cancer within 3 years of first planned dose, except for tumors with negligible risk of metastasis or death (e.g., adequately treated cutaneous squamous cell carcinoma, basal cell carcinoma, ductal carcinoma in situ of breast). Patients with hematologic malignancies are excluded.",
      "quote": "Concurrent malignancy other than cervical cancer and/or history of malignancy other than cervical cancer within 3 years of date of first planned dose of study drug",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any acute or chronic psychiatric problems that, in the opinion of the investigator, make the patient ineligible for participation.",
      "quote": "Any acute or chronic psychiatric problems that, in the opinion of the investigator, make the patient ineligible for participation.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with a history of solid organ transplant (prior corneal transplants may be allowed after discussion with and approval from the medical monitor).",
      "quote": "Patients with a history of solid organ transplant",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any medical co-morbidity, physical examination finding, or metabolic dysfunction, or clinical laboratory abnormality that, in the opinion of the investigator, renders the patient unsuitable for participation due to high safety risks and/or potential to affect interpretation of results.",
      "quote": "Any medical co-morbidity, physical examination finding, or metabolic dysfunction, or clinical laboratory abnormality that, in the opinion of the investigator, renders the patient unsuitable for participation in a clinical trial due to high safety risks and/or potential to affect interpretation of results of the study.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Pregnant or breastfeeding women.",
      "quote": "Pregnant or breastfeeding women.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Women of childbearing potential who are unwilling to practice highly effective contraception prior to initial study drug treatment, during the study, and for at least 6 months after the last dose. Highly effective methods include stable use of hormonal contraception, IUD, intrauterine hormone-releasing system, bilateral tubal ligation, vasectomized partner, or sexual abstinence. Postmenopausal women must be amenorrheic for at least 12 months.",
      "quote": "Women of childbearing potential* who are unwilling to practice highly effective contraception prior to the initial study drug treatment, during the study, and for at least 6 months after the last dose.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients committed to an institution by virtue of an order issued by either the judicial or the administrative authorities will be excluded from this study.",
      "quote": "Patients committed to an institution by virtue of an order issued by either the judicial or the administrative authorities will be excluded from this study.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with idelalisib.",
      "quote": "Prior treatment with idelalisib.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with live vaccines within 30 days of initial administration of study drug. Patients must not be treated with live vaccines during the study and up to 5 half-lives following the last dose.",
      "quote": "Prior treatment with live vaccines within 30 days of initial administration of study drug",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with prior treatment on any clinical trial within 30 days of the initial administration of study drug. Non-interventional and observational trials are acceptable.",
      "quote": "Patients with prior treatment on any clinical trial within 30 days of the initial administration of study drug.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Member of the clinical site study team and/or his or her immediate family.",
      "quote": "Member of the clinical site study team and/or his or her immediate family.",
      "thresholds": []
    }
  ]
}
